  "plot_script": "import numpy as np\nimport matplotlib.pyplot as plt\nfrom scipy.stats import norm, t, skewnorm\n\nstrategies = [\n    {'title': 'WP-guided fourth downs and 2-point tries', 'family': 'skew_normal', 'most_plausible': 0.44, 'params': {'xi': 0.221, 'omega': 0.409, 'alpha': 1.3}},\n    {'title': 'Neutral early-down pass/play-action bias', 'family': 'skew_normal', 'most_plausible': 0.31, 'params': {'xi': 0.131, 'omega': 0.345, 'alpha': 1.1}},\n    {'title': 'Coverage-first pressure discipline', 'family': 'normal', 'most_plausible': 0.23, 'params': {'mu': 0.23, 'sigma': 0.290816}},\n    {'title': 'Timeouts as play-quality insurance', 'family': 'normal', 'most_plausible': 0.04, 'params': {'mu': 0.04, 'sigma': 0.142857}},\n    {'title': 'Selective shock tempo', 'family': 'student_t', 'most_plausible': 0.13, 'params': {'nu': 7, 'mu': 0.13, 'sigma': 0.241525}},\n    {'title': 'Pass-rush freshness rotation', 'family': 'skew_normal', 'most_plausible': 0.09, 'params': {'xi': 0.230, 'omega': 0.295, 'alpha': -3.0}}\n]\n\ndef make_dist(s):\n    p = s['params']\n    if s['family'] == 'normal':\n        return norm(loc=p['mu'], scale=p['sigma'])\n    if s['family'] == 'student_t':\n        return t(df=p['nu'], loc=p['mu'], scale=p['sigma'])\n    if s['family'] == 'skew_normal':\n        return skewnorm(a=p['alpha'], loc=p['xi'], scale=p['omega'])\n    raise ValueError('Unknown family: {}'.format(s['family']))\n\nfig, axes = plt.subplots(3, 2, figsize=(12, 10), constrained_layout=True)\naxes = axes.ravel()\n\nfor ax, s in zip(axes, strategies):\n    dist = make_dist(s)\n    lo, hi = dist.ppf([0.025, 0.975])\n    xlo, xhi = dist.ppf([0.001, 0.999])\n    xlo = min(xlo, lo, s['most_plausible'])\n    xhi = max(xhi, hi, s['most_plausible'])\n    pad = 0.10 * (xhi - xlo)\n    x = np.linspace(xlo - pad, xhi + pad, 700)\n    y = dist.pdf(x)\n\n    ax.plot(x, y, color='black', linewidth=1.8)\n    mask = (x >= lo) & (x <= hi)\n    ax.fill_between(x[mask], 0, y[mask], color='ste